import{_ as t,c as n,o as r,j as s,Y as o,t as i}from"./chunks/framework.D-NV0Bun.js";const P=JSON.parse('{"title":"ipcclean | x-cmd man (ip man1) | 从退出的PostgreSQL服务器中删除共享内存和信号灯","titleTemplate":false,"description":"x-cmd man (ip man1 Manual Page) | ipcclean - 从退出的PostgreSQL服务器中删除共享内存和信号灯","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"ipcclean | x-cmd man (ip man1) | 从退出的PostgreSQL服务器中删除共享内存和信号灯"}],["meta",{"name":"og:description","content":"x-cmd man (ip man1 Manual Page) | ipcclean - 从退出的PostgreSQL服务器中删除共享内存和信号灯"}]]},"headers":[],"params":{"isMan":true,"man":"ipcclean","category":"ip man1","desc":"从退出的PostgreSQL服务器中删除共享内存和信号灯"},"relativePath":"ip/man1/ipcclean.md","filePath":"ip/man1/[man].md"}'),p={name:"ip/man1/ipcclean.md"},c={class:"visually-hidden"};function l(e,a,m,h,d,g){return r(),n("div",null,[s("h1",c,i(e.$params.man),1),a[0]||(a[0]=o('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>ipcclean - 从退出的PostgreSQL服务器中删除共享内存和信号灯</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><p><strong>ipcclean</strong></p><h2 id="description-描述" tabindex="-1">DESCRIPTION 描述 <a class="header-anchor" href="#description-描述" aria-label="Permalink to &quot;DESCRIPTION 描述&quot;">​</a></h2><p><strong>ipcclean</strong> 删除当前用户拥有的所有共享内存段和信号灯集。 它的目地是在 PostgreSQL 服务器 （<strong>postmaster</strong>(1)）崩溃之后进行清理。 请注意的是立 即重起服务器也会清理共享内存和信号灯，所以这条命令实际上用处不大。</p><p>应该只有数据库管理员可以运行这条命令，因为如果在多用户的环境中执行， 它会 导致怪异的行为（也就是说，崩溃）。 如果在服务器运行时执行这条命令， 服务 器分配的共享内存和信号灯将被删除。 这通常会导致该服务器启动的后端服务器的 普遍失败。</p><h2 id="notes-注意" tabindex="-1">NOTES 注意 <a class="header-anchor" href="#notes-注意" aria-label="Permalink to &quot;NOTES 注意&quot;">​</a></h2><p>这个脚本是个&quot;hack&quot;，但是从写成它的这些年来， 没有人提出等效的可移植的解决 方法。因为 <strong>postmaster</strong> 现在可以清理自己，所以以后很可能不会继续改进 ipcclean。</p><p>这个脚本对 <strong>ipcs</strong> 工具的输出做了一些假设， 而这些假设可能在不同的操作 系统间是不同的。因此，它可能不能在你的系统上运行。</p><h2 id="译者" tabindex="-1">译者 <a class="header-anchor" href="#译者" aria-label="Permalink to &quot;译者&quot;">​</a></h2><p><strong>Postgresql 中文网站</strong> <strong>何伟平 &lt;laser@pgsqldb.org&gt;</strong></p><h2 id="跋" tabindex="-1">跋 <a class="header-anchor" href="#跋" aria-label="Permalink to &quot;跋&quot;">​</a></h2><p><br> 本页面中文版由中文 man 手册页计划提供。 <br> 中文 man 手册页计划：<strong><a href="https://github.com/man-pages-zh/manpages-zh" target="_blank" rel="noreferrer">https://github.com/man-pages-zh/manpages-zh</a></strong></p>',14))])}const S=t(p,[["render",l]]);export{P as __pageData,S as default};
